#!/usr/bin/env bash
# prometheus-community/prometheus-blackbox-exporter 11.10.0 - base variant: cluster-metrics-readonly
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/prometheus-community-prometheus-blackbox-exporter-11-10-0.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install it with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the cluster-metrics-readonly base variant into ./prometheus-community-prometheus-blackbox-exporter-11-10-0-cluster-metrics-readonly"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/prometheus-community-prometheus-blackbox-exporter:11.10.0 --base cluster-metrics-readonly --work-dir ./prometheus-community-prometheus-blackbox-exporter-11-10-0-cluster-metrics-readonly --non-interactive --namespace default

say "Read what was rendered; nothing has touched the cluster yet"
ls ./prometheus-community-prometheus-blackbox-exporter-11-10-0-cluster-metrics-readonly/out/manifests

say "Ensure the default namespace exists"
kubectl create namespace default --dry-run=client -o yaml | kubectl apply -f -

if [ -d ./prometheus-community-prometheus-blackbox-exporter-11-10-0-cluster-metrics-readonly/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./prometheus-community-prometheus-blackbox-exporter-11-10-0-cluster-metrics-readonly/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./prometheus-community-prometheus-blackbox-exporter-11-10-0-cluster-metrics-readonly/out/manifests

say "Done. The cluster received exactly the files in ./prometheus-community-prometheus-blackbox-exporter-11-10-0-cluster-metrics-readonly/out."
